</svg></div><div class="side"><div class="readouts"><div class="readout"><div class="name" id="hopsout-name">Hops followed (hops)</div><output id="hopsout" data-synapse-readout="hopsout" aria-labelledby="hopsout-name"></output></div><div class="readout"><div class="name" id="factsout-name">Facts reached (nodes)</div><output id="factsout" data-synapse-readout="factsout" aria-labelledby="factsout-name"></output></div><div class="readout"><div class="name" id="answerout-name">Answer found (1 = yes, 0 = no)</div><output id="answerout" data-synapse-readout="answerout" aria-labelledby="answerout-name"></output></div></div><p id="found" class="card found" aria-live="polite"></p><details class="card fine"><summary>Keyboard controls</summary><div class="row"><label for="hops">Hops followed</label><input type="range" id="hops" data-synapse-control="hops" min="0" max="2" step="1" value="0" data-unit="hops" aria-valuetext="0 hops"></div></details></div></section><section class="card hints"><h2>Need a hint?</h2><details><summary>Hint 1</summary><p>Look at the links leaving Petronas Towers. None of them goes straight to a country, so which dot could lead there?</p></details><details><summary>Hint 2</summary><p>Follow the link from Kuala Lumpur. Each extra hop also reaches facts that are not the answer, so the number of facts reached grows faster than the number of hops.</p></details></section><section class="explain"><h2>Why it happens</h2><p>Each link in a knowledge graph is one fact, such as &quot;Petronas Towers is in Kuala Lumpur&quot; or &quot;Kuala Lumpur is in Malaysia&quot;. No single fact joins the towers to Malaysia. The search starts at the dot named in the question and follows one link to reach Kuala Lumpur. It then follows a second link from Kuala Lumpur to reach Malaysia. Chaining two facts in this way is called a two-hop answer.</p><p>Every hop also pulls in neighbours that are not useful, like Argentina (where the architect was born). So a search must keep track of which dots it has reached and which links lead onward. More hops reach more facts, but the extra facts can include many wrong ones. That is why a good search follows only the links that match the question.</p></section></main><script>
addEventListener("message", function (e) {
  var d = e.data;
  if (d && typeof d === "object" && d.type === "synapse_theme" && (d.theme === "light" || d.theme === "dark")) document.documentElement.setAttribute("data-theme", d.theme);
});
Array.prototype.forEach.call(document.querySelectorAll("input[data-synapse-control]"), function (el) {
  function say() { el.setAttribute("aria-valuetext", el.value + (el.dataset.unit ? " " + el.dataset.unit : "")); }
  el.addEventListener("input", say);
  say();
});

(function () {
var levelCounts = [1, 3, 4];
var nodes = [
  { id: "q", level: 0 },
  { id: "kl", level: 1 },
  { id: "pelli", level: 1 },
  { id: "h", level: 1 },
  { id: "mal", level: 2 },
  { id: "sel", level: 2 },
  { id: "arg", level: 2 },
  { id: "tall", level: 2 }
];
var TRACK_LEFT = 55;
var TRACK_RIGHT = 345;
var svg = document.getElementById("bench-art");
var ctl = document.getElementById("hops");
var handle = svg.querySelector("[data-synapse-handle]");

function factsReached(hops) {
  var total = 0;
  for (var i = 0; i <= hops; i++) {
    total += levelCounts[i];
  }
  return total;
}

function answerFound(hops) {
  return hops >= 2 ? 1 : 0;
}

function handleX(hops) {
  var lo = Number(ctl.min);
  var hi = Number(ctl.max);
  return TRACK_LEFT + (hops - lo) / (hi - lo) * (TRACK_RIGHT - TRACK_LEFT);
}

function update() {
  var hops = Number(ctl.value);
  var facts = factsReached(hops);
  var found = answerFound(hops);
  for (var i = 0; i < nodes.length; i++) {
    var n = nodes[i];
    var reached = n.level <= hops;
    var el = document.getElementById("n-" + n.id);
    el.style.fill = reached ? "var(--accent)" : "var(--card)";
    el.style.strokeWidth = (n.id === "mal" && found === 1) ? "5" : "2";
    el.style.stroke = (n.id === "mal" && found === 1) ? "var(--fg)" : "var(--border)";
    var edge = document.getElementById("e-" + n.id);
    if (edge) {
      edge.style.opacity = reached ? "1" : "0.2";
    }
  }
  handle.setAttribute("cx", String(handleX(hops)));
  document.getElementById("hopsout").textContent = hops + (hops === 1 ? " hop" : " hops");
  document.getElementById("factsout").textContent = facts + " nodes";
  document.getElementById("answerout").textContent = found + (found === 1 ? " (yes)" : " (no)");
  var msg = found === 1 ? "the answer Malaysia is found" : "the answer Malaysia is not found yet";
  svg.setAttribute("aria-label", "Knowledge graph, " + hops + " hops followed, " + facts + " nodes reached, " + msg);
  document.getElementById("found").textContent = "After " + hops + (hops === 1 ? " hop" : " hops") + " the search has reached " + facts + " nodes, so " + msg + ".";
}

var dragging = false;
handle.addEventListener("pointerdown", function (e) {
  dragging = true;
  handle.setPointerCapture(e.pointerId);
  e.preventDefault();
});
handle.addEventListener("pointermove", function (e) {
  if (!dragging) { return; }
  var rect = svg.getBoundingClientRect();
  var x = (e.clientX - rect.left) / rect.width * 400;
  var lo = Number(ctl.min);
  var hi = Number(ctl.max);
  var step = Number(ctl.step);
  var v = lo + (x - TRACK_LEFT) / (TRACK_RIGHT - TRACK_LEFT) * (hi - lo);
  v = Math.round((v - lo) / step) * step + lo;
  v = Math.max(lo, Math.min(hi, v));
  ctl.value = String(v);
  ctl.dispatchEvent(new Event("input", { bubbles: true }));
});
handle.addEventListener("pointerup", function (e) {
  dragging = false;
  if (handle.hasPointerCapture(e.pointerId)) {
    handle.releasePointerCapture(e.pointerId);
  }
});
ctl.addEventListener("input", update);
update();
})();</script></body></html>","citations":[{"source":"UNVERIFIED (no textbook page has been checked for this Environment)","page":null,"quote":null,"verified":false,"printedPage":null}],"checked":{"layers":["postprocess","scan","render","wording"],"controlsExercised":1,"gridPoints":0,"referenceCases":0,"readouts":3,"models":[],"limits":"Written whole by a model and not built on the Kit, so none of its numbers or formulas were compared with an audited science model. Code checked that it runs and that its controls work and a second model read its words and formulas, but only for a short, scripted stretch of time. No textbook source was checked and a person has not reviewed it. Check it against your textbook."},"planSummary":"A simple page written whole by a model, the last step when no fuller lab passed its checks (topic none)."}}
